class UnionFind {
  constructor() {
    // Each element starts as its own parent
    this.parent = {};
    // Track the size/rank of each set for union by rank
    this.rank = {};
  }

  // Create a new set with a single element
  makeSet(x) {
    if (!(x in this.parent)) {
      this.parent[x] = x;
      this.rank[x] = 0;
    }
  }

  // Find the representative (root) of the set containing x
  // Uses path compression for efficiency
  find(x) {
    if (!(x in this.parent)) {
      this.makeSet(x);
    }

    // Path compression: make all nodes on the path
    // point directly to the root
    if (x !== this.parent[x]) {
      this.parent[x] = this.find(this.parent[x]);
    }

    return this.parent[x];
  }

  // Merge the sets containing x and y
  // Uses union by rank for efficiency
  union(x, y) {
    const rootX = this.find(x);
    const rootY = this.find(y);

    // Already in the same set
    if (rootX === rootY) {
      return;
    }

    // Union by rank: attach smaller rank tree under root of higher rank tree
    if (this.rank[rootX] < this.rank[rootY]) {
      this.parent[rootX] = rootY;
    } else if (this.rank[rootX] > this.rank[rootY]) {
      this.parent[rootY] = rootX;
    } else {
      // Same rank, make one the parent and increment its rank
      this.parent[rootY] = rootX;
      this.rank[rootX]++;
    }
  }

  // Check if two elements are in the same set
  connected(x, y) {
    return this.find(x) === this.find(y);
  }

  // Get all sets as arrays of elements
  getSets() {
    const sets = {};

    // Group elements by their root
    for (const element in this.parent) {
      const root = this.find(element);
      if (!sets[root]) {
        sets[root] = [];
      }
      sets[root].push(element);
    }

    // Convert to array of sets
    return Object.values(sets);
  }
}

// Example usage
const uf = new UnionFind();

// Create initial sets
for (const element of ['A', 'B', 'C', 'D', 'E', 'F', 'G']) {
  uf.makeSet(element);
}

// Perform some unions
uf.union('A', 'B');
uf.union('B', 'C');
uf.union('D', 'E');
uf.union('F', 'G');

console.log('Sets after initial unions:', uf.getSets());
console.log('Are A and C connected?', uf.connected('A', 'C'));
console.log('Are A and D connected?', uf.connected('A', 'D'));

// Merge two sets
uf.union('C', 'D');
console.log('Sets after merging C and D:', uf.getSets());
console.log('Are A and E connected now?', uf.connected('A', 'E'));
